    fn can_parse_expr(&self) -> bool { self.at_pratt_unary_expr() || self.can_parse_ident_expr() || self.can_parse_string_expr() || self.can_parse_number_expr() || self.can_parse_let_expr() || self.can_parse_thunk_expr() || self.can_parse_force_expr() || self.can_parse_match_expr() || self.can_parse_handle_expr() || self.can_parse_bundle_expr() || self.can_parse_if_else_expr() || self.can_parse_block_expr() || self.can_parse_paren_expr() || self.can_parse_annotation_expr() || self.can_parse_lambda_expr() || self.can_parse_perform_expr() }
    fn parse_expr(&mut self) -> SyntaxNode {
        self.parse_expr_bp(0)
    }

    fn parse_expr_bp(&mut self, min_bp: u8) -> SyntaxNode {
        let mut lhs = self.parse_expr_atom();
        loop {
            // MemberExpr (lbp=90)
            if self.at_pratt_member_expr() && 90 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol(".", &mut children);
                self.skip_trivia_into(&mut children);
                if matches!(self.current().map(|t| &t.kind), Some(LexKind::Ident)) {
                    children.push(SyntaxElement::Token(self.bump().unwrap()));
                } else { self.error_here("expected Ident"); }
                lhs = node_from_children(SyntaxKind::MEMBER_EXPR, children);
                continue;
            }
            // CallExpr (lbp=90)
            if self.at_pratt_call_expr() && 90 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol("(", &mut children);
                children.push(SyntaxElement::Node(Box::new(self.parse_call_arg_items())));
                self.expect_symbol(")", &mut children);
                lhs = node_from_children(SyntaxKind::CALL_EXPR, children);
                continue;
            }
            // BinaryExpr (lbp=30)
            if self.at_pratt_binary_expr() && 30 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol("*", &mut children);
                self.expect_symbol("/", &mut children);
                self.expect_symbol("%", &mut children);
                lhs = node_from_children(SyntaxKind::BINARY_EXPR, children);
                continue;
            }
            // BinaryExpr (lbp=20)
            if self.at_pratt_binary_expr() && 20 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol("+", &mut children);
                self.expect_symbol("-", &mut children);
                lhs = node_from_children(SyntaxKind::BINARY_EXPR, children);
                continue;
            }
            // BinaryExpr (lbp=10)
            if self.at_pratt_binary_expr() && 10 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol("==", &mut children);
                self.expect_symbol("!=", &mut children);
                self.expect_symbol("<", &mut children);
                self.expect_symbol("<=", &mut children);
                self.expect_symbol(">", &mut children);
                self.expect_symbol(">=", &mut children);
                lhs = node_from_children(SyntaxKind::BINARY_EXPR, children);
                continue;
            }
            // BinaryExpr (lbp=5)
            if self.at_pratt_binary_expr() && 5 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol("&&", &mut children);
                lhs = node_from_children(SyntaxKind::BINARY_EXPR, children);
                continue;
            }
            // BinaryExpr (lbp=3)
            if self.at_pratt_binary_expr() && 3 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol("||", &mut children);
                lhs = node_from_children(SyntaxKind::BINARY_EXPR, children);
                continue;
            }
            // AssignExpr (lbp=1)
            if self.at_pratt_assign_expr() && 1 > min_bp {
                let mut children = vec![SyntaxElement::Node(Box::new(lhs))];
                self.expect_symbol("=", &mut children);
                children.push(SyntaxElement::Node(Box::new(self.parse_expr_bp(1))));
                self.expect_symbol(";", &mut children);
                children.push(SyntaxElement::Node(Box::new(self.parse_expr_bp(1))));
                lhs = node_from_children(SyntaxKind::ASSIGN_EXPR, children);
                continue;
            }
            break;
        }
        lhs
    }

    fn parse_expr_atom(&mut self) -> SyntaxNode {
        if self.at_pratt_unary_expr() {
            let mut children = Vec::new();
            self.expect_symbol("-", &mut children);
            self.expect_symbol("!", &mut children);
            return node_from_children(SyntaxKind::UNARY_EXPR, children);
        }
        if self.can_parse_ident_expr() { return self.parse_ident_expr(); }
        if self.can_parse_string_expr() { return self.parse_string_expr(); }
        if self.can_parse_number_expr() { return self.parse_number_expr(); }
        if self.can_parse_let_expr() { return self.parse_let_expr(); }
        if self.can_parse_thunk_expr() { return self.parse_thunk_expr(); }
        if self.can_parse_force_expr() { return self.parse_force_expr(); }
        if self.can_parse_match_expr() { return self.parse_match_expr(); }
        if self.can_parse_handle_expr() { return self.parse_handle_expr(); }
        if self.can_parse_bundle_expr() { return self.parse_bundle_expr(); }
        if self.can_parse_if_else_expr() { return self.parse_if_else_expr(); }
        if self.can_parse_block_expr() { return self.parse_block_expr(); }
        if self.can_parse_paren_expr() { return self.parse_paren_expr(); }
        if self.can_parse_annotation_expr() { return self.parse_annotation_expr(); }
        if self.can_parse_lambda_expr() { return self.parse_lambda_expr(); }
        if self.can_parse_perform_expr() { return self.parse_perform_expr(); }
        self.error_here("expected expression");
        node_from_children(SyntaxKind::ERROR, Vec::new())
    }

    fn at_pratt_unary_expr(&self) -> bool { self.at_non_trivia_symbol("-") }
    fn at_pratt_member_expr(&self) -> bool { self.at_non_trivia_symbol(".") }
    fn at_pratt_call_expr(&self) -> bool { self.at_non_trivia_symbol("(") }
    fn at_pratt_binary_expr(&self) -> bool { self.at_non_trivia_symbol("*") }
    fn at_pratt_assign_expr(&self) -> bool { self.at_non_trivia_symbol("=") }
    fn can_parse_call_arg_items(&self) -> bool { self.can_parse_expr() }
    fn parse_call_arg_items(&mut self) -> SyntaxNode {
        let mut children = Vec::new();
        children.push(SyntaxElement::Node(Box::new(self.parse_expr())));
        while self.at_non_trivia_symbol(",") {
            self.expect_symbol(",", &mut children);
            children.push(SyntaxElement::Node(Box::new(self.parse_expr())));
        }
        if self.at_non_trivia_symbol(",") {
            self.expect_symbol(",", &mut children);
        }
        node_from_children(SyntaxKind::CALL_ARG_ITEMS, children)
    }

    fn can_parse_ident_expr(&self) -> bool { self.at_non_trivia_ident() }
