        while self.can_parse_bundle_entry() {
            children.push(SyntaxElement::Node(Box::new(self.parse_bundle_entry())));
        }
        self.expect_symbol("}", &mut children);
        node_from_children(SyntaxKind::BUNDLE_EXPR, children)
